import { cn } from "@/lib/utils";
import React, { useEffect, useRef } from "react";
import { createSpringFollower, type SpringFollower } from "./motion-curves";

export interface TiltedCardProps extends React.HTMLAttributes<HTMLDivElement> {
  children: React.ReactNode;
  tiltIntensity?: number; // Maximum rotation in degrees (e.g., 15)
  glareOpacity?: number; // Maximum opacity of the glare effect (0 to 1)
  scaleOnHover?: number; // Scale factor when hovered (e.g., 1.05)
  initialScale?: number; // Starting scale factor (e.g., 1 or 1.05 for featured cards)
  innerClassName?: string;
  glareClassName?: string;
  showShadow?: boolean;
}

// Pointer tilt: every frame the tilt chases the pointer through this spring,
// keeping its velocity when the pointer moves on — no animation library, just
// the spring's equation of motion stepped on requestAnimationFrame.
const TILT_SPRING = { damping: 25, stiffness: 300, mass: 0.5, restDelta: 0.001, restSpeed: 0.01 };
// Hover scale, same approach, so leaving mid-grow springs back from where it is.
const HOVER_SPRING = { stiffness: 300, damping: 20, mass: 1, restDelta: 0.005, restSpeed: 0.01 };

/** Maps -1..1 onto `from..to`, clamped at both ends. */
const mapRange = (v: number, from: number, to: number) => {
  const p = Math.min(Math.max((v + 1) / 2, 0), 1);
  return from + (to - from) * p;
};

const glareBackground = (x: number, y: number) =>
  `radial-gradient(circle at ${x}% ${y}%, var(--theme-color,var(--pricing-accent,var(--primary))), transparent 65%)`;

export const TiltedCard = React.forwardRef<HTMLDivElement, TiltedCardProps>(
  (
    {
      children,
      className,
      tiltIntensity = 15,
      glareOpacity = 0.2,
      scaleOnHover = 1.02,
      initialScale = 1,
      innerClassName,
      glareClassName,
      showShadow = true,
      ...props
    },
    ref,
  ) => {
    const cardRef = useRef<HTMLDivElement>(null);
    const glareRef = useRef<HTMLDivElement>(null);

    React.useImperativeHandle(ref, () => cardRef.current as HTMLDivElement);

    // Read at paint time, so a changed prop applies from the next frame.
    const latest = useRef({ tiltIntensity, scaleOnHover, initialScale });
    latest.current = { tiltIntensity, scaleOnHover, initialScale };

    const springs = useRef<{
      x: SpringFollower;
      y: SpringFollower;
      scale: SpringFollower;
    } | null>(null);

    useEffect(() => {
      // Writes the card transform and the glare straight to the DOM, the way
      // motion values do — no React render per frame.
      const paint = () => {
        const s = springs.current;
        const card = cardRef.current;
        if (!s || !card) return;
        const tilt = latest.current.tiltIntensity;
        const x = s.x.get();
        const y = s.y.get();
        const scale = s.scale.get();
        const rotateX = mapRange(y, tilt, -tilt);
        const rotateY = mapRange(x, -tilt, tilt);
        const parts: string[] = [];
        if (scale !== 1) parts.push(`scale(${scale})`);
        if (rotateX !== 0) parts.push(`rotateX(${rotateX}deg)`);
        if (rotateY !== 0) parts.push(`rotateY(${rotateY}deg)`);
        card.style.transform = parts.length ? parts.join(" ") : "none";
        if (glareRef.current) {
          glareRef.current.style.background = glareBackground(
            mapRange(x, 0, 100),
            mapRange(y, 0, 100),
          );
        }
      };

      springs.current = {
        x: createSpringFollower(0, paint, TILT_SPRING),
        y: createSpringFollower(0, paint, TILT_SPRING),
        scale: createSpringFollower(initialScale, paint, HOVER_SPRING),
      };

      paint();

      return () => {
        springs.current?.x.destroy();
        springs.current?.y.destroy();
        springs.current?.scale.destroy();
        springs.current = null;
      };
    }, [initialScale]);

    const handleMouseMove = (e: React.MouseEvent<HTMLDivElement>) => {
      if (!cardRef.current) return;
      const rect = cardRef.current.getBoundingClientRect();
      const x = (e.clientX - rect.left) / rect.width - 0.5;
      const y = (e.clientY - rect.top) / rect.height - 0.5;
      springs.current?.x.set(x * 2);
      springs.current?.y.set(y * 2);
    };

    const handleMouseLeave = () => {
      springs.current?.x.set(0);
      springs.current?.y.set(0);
    };

    // Hover scale follows a mouse or pen; a touch never counts as hovering.
    const handlePointerEnter = (e: React.PointerEvent<HTMLDivElement>) => {
      if (e.pointerType === "touch") return;
      springs.current?.scale.set(latest.current.scaleOnHover);
    };

    const handlePointerLeave = (e: React.PointerEvent<HTMLDivElement>) => {
      if (e.pointerType === "touch") return;
      springs.current?.scale.set(latest.current.initialScale);
    };

    return (
      <div
        className={cn("relative perspective-[1000px] w-full h-full", className)}
        {...props}
      >
        <div
          ref={cardRef}
          onMouseMove={handleMouseMove}
          onMouseLeave={handleMouseLeave}
          onPointerEnter={handlePointerEnter}
          onPointerLeave={handlePointerLeave}
          style={{
            transformStyle: "preserve-3d",
            transform: initialScale !== 1 ? `scale(${initialScale})` : undefined,
          }}
          className={cn(
            "relative w-full h-full rounded-2xl overflow-visible transition-shadow duration-300 group cursor-pointer",
            showShadow &&
              "shadow-[0_10px_30px_rgba(0,0,0,0.08)] dark:shadow-[0_10px_30px_rgba(0,0,0,0.5)] hover:shadow-[0_20px_40px_rgba(0,0,0,0.14)] dark:hover:shadow-[0_20px_40px_rgba(0,0,0,0.7)]",
            innerClassName,
          )}
        >
          <div
            className="relative w-full h-full z-10"
            style={
              {
                transform: "translateZ(30px)",
                "--glare-opacity": glareOpacity,
              } as React.CSSProperties
            }
          >
            {children}

            {/* Dynamic Theme Color Glare Overlay */}
            <div
              ref={glareRef}
              className={cn(
                "absolute inset-0 z-50 pointer-events-none opacity-0 group-hover:opacity-[var(--glare-opacity)] transition-opacity duration-300 rounded-2xl",
                glareClassName,
              )}
              style={{ background: glareBackground(50, 50) }}
            />
          </div>
        </div>
      </div>
    );
  },
);
TiltedCard.displayName = "TiltedCard";

/**
 * Motion curves with no animation library behind them.
 *
 * The components here ship as CSS, GSAP or Motion builds that must move
 * identically, so the curves are computed once, from the same numbers, and
 * handed to whichever engine runs them:
 *
 *   - `cubicBezier(x1, y1, x2, y2)` → an easing function (GSAP accepts any
 *     `(progress) => value` as `ease`), exact for Motion's `ease: [..]` arrays
 *     and for CSS `cubic-bezier()`.
 *   - `spring({ stiffness, damping, mass })` → the analytic solution Motion
 *     Motion uses, as an easing function plus the time it takes to settle, or
 *     as a CSS `linear()` string for a fixed start and end.
 *   - `createSpringFollower` → a value that chases a moving target through the
 *     same spring every frame, like Motion's `useSpring`, for pointer-driven
 *     motion that no fixed curve can describe.
 */

// ---------------------------------------------------------------------------
// Cubic bezier
// ---------------------------------------------------------------------------

/**
 * The CSS / Motion cubic-bezier as a function of progress. Newton-Raphson
 * with a bisection fallback, the same solver browsers use.
 */
export function cubicBezier(x1: number, y1: number, x2: number, y2: number) {
  if (x1 === y1 && x2 === y2) return (t: number) => t;

  const a = (p1: number, p2: number) => 1 - 3 * p2 + 3 * p1;
  const b = (p1: number, p2: number) => 3 * p2 - 6 * p1;
  const c = (p1: number) => 3 * p1;
  const at = (t: number, p1: number, p2: number) =>
    ((a(p1, p2) * t + b(p1, p2)) * t + c(p1)) * t;
  const slope = (t: number, p1: number, p2: number) =>
    3 * a(p1, p2) * t * t + 2 * b(p1, p2) * t + c(p1);

  const solveX = (x: number) => {
    let t = x;
    for (let i = 0; i < 8; i++) {
      const s = slope(t, x1, x2);
      if (Math.abs(s) < 1e-6) break;
      const err = at(t, x1, x2) - x;
      if (Math.abs(err) < 1e-7) return t;
      t -= err / s;
    }
    let lo = 0;
    let hi = 1;
    t = x;
    for (let i = 0; i < 30 && hi - lo > 1e-7; i++) {
      const value = at(t, x1, x2);
      if (value < x) lo = t;
      else hi = t;
      t = (lo + hi) / 2;
    }
    return t;
  };

  return (x: number) => (x <= 0 ? 0 : x >= 1 ? 1 : at(solveX(x), y1, y2));
}

/** Motion's named eases, as the cubic-beziers they are. */
export const MOTION_EASE = {
  linear: [0, 0, 1, 1],
  easeIn: [0.42, 0, 1, 1],
  easeOut: [0, 0, 0.58, 1],
  easeInOut: [0.42, 0, 0.58, 1],
  circIn: [0.55, 0, 1, 0.45],
  circOut: [0.55, 0, 0.45, 1],
  circInOut: [0.85, 0, 0.15, 1],
  backIn: [0.31, 0.01, 0.66, -0.59],
  backOut: [0.33, 1.53, 0.69, 0.99],
  anticipate: [0.66, -0.56, 0.34, 1.35],
} as const;

/**
 * Motion's default layout transition (`layout` / `layoutId`):
 * `{ duration: 0.45, ease: [0.4, 0, 0.1, 1] }`.
 */
export const LAYOUT_TRANSITION = { duration: 0.45, ease: [0.4, 0, 0.1, 1] as const };

// ---------------------------------------------------------------------------
// Spring
// ---------------------------------------------------------------------------

export interface SpringOptions {
  /** Motion default 100. */
  stiffness?: number;
  /** Motion default 10. */
  damping?: number;
  /** Motion default 1. */
  mass?: number;
  /** Starting velocity, in units of the whole distance per second. */
  velocity?: number;
  /** How close to the end counts as settled, as a fraction of the distance. */
  restDelta?: number;
}

/**
 * Normalised position (0 → 1) of a spring released from 0 towards 1, at time
 * `t` seconds. The closed-form solution Motion's `spring()` generator
 * uses for the under-, critically and over-damped cases.
 */
export function springAt(options: SpringOptions = {}) {
  const { stiffness = 100, damping = 10, mass = 1, velocity = 0 } = options;
  const zeta = damping / (2 * Math.sqrt(stiffness * mass));
  const omega0 = Math.sqrt(stiffness / mass);
  // Motion's convention: distance still to cover, velocity toward it negated.
  const delta = 1;
  const v0 = -velocity;

  if (zeta < 1) {
    const omegaD = omega0 * Math.sqrt(1 - zeta * zeta);
    return (t: number) => {
      const envelope = Math.exp(-zeta * omega0 * t);
      return (
        1 -
        envelope *
          (((v0 + zeta * omega0 * delta) / omegaD) * Math.sin(omegaD * t) +
            delta * Math.cos(omegaD * t))
      );
    };
  }
  if (zeta === 1) {
    return (t: number) => 1 - Math.exp(-omega0 * t) * (delta + (v0 + omega0 * delta) * t);
  }
  const omegaD = omega0 * Math.sqrt(zeta * zeta - 1);
  return (t: number) => {
    const envelope = Math.exp(-zeta * omega0 * t);
    const freq = Math.min(omegaD * t, 300);
    return (
      1 -
      (envelope *
        ((v0 + zeta * omega0 * delta) * Math.sinh(freq) + omegaD * delta * Math.cosh(freq))) /
        omegaD
    );
  };
}

/** Seconds until the spring stays within `restDelta` of its end. */
export function springDuration(options: SpringOptions = {}) {
  const at = springAt(options);
  const restDelta = options.restDelta ?? 0.001;
  const step = 1 / 240;
  let lastOutside = 0;
  for (let t = 0; t <= 10; t += step) {
    if (Math.abs(1 - at(t)) > restDelta) lastOutside = t;
    else if (t - lastOutside > 0.1) break;
  }
  return Math.max(lastOutside + step, step);
}

/**
 * A spring as a duration and an easing function over it — what GSAP takes:
 *
 *   const { duration, ease } = springEase({ stiffness: 300, damping: 20 });
 *   gsap.to(el, { y: 0, duration, ease });
 *
 * Exact for a fixed start and end; a spring that has to react mid-flight to a
 * new target needs `createSpringFollower` instead.
 */
export function springEase(options: SpringOptions = {}) {
  const duration = springDuration(options);
  const at = springAt(options);
  return {
    duration,
    ease: (progress: number) => (progress >= 1 ? 1 : at(progress * duration)),
  };
}

/**
 * A spring as a CSS `linear()` easing and its duration in ms, for
 * `transition` / `animation` with a fixed start and end.
 *
 *   const { easing, duration } = springLinear({ stiffness: 400, damping: 30 });
 *   el.style.transition = `transform ${duration}ms ${easing}`;
 */
export function springLinear(options: SpringOptions = {}, pointsPerSecond = 60) {
  const duration = springDuration(options);
  const at = springAt(options);
  const count = Math.max(Math.ceil(duration * pointsPerSecond), 8);
  const points: string[] = [];
  for (let i = 0; i <= count; i++) {
    const t = (i / count) * duration;
    points.push(String(Math.round((i === count ? 1 : at(t)) * 10000) / 10000));
  }
  return { easing: `linear(${points.join(", ")})`, duration: Math.round(duration * 1000) };
}

// ---------------------------------------------------------------------------
// Spring follower (useSpring equivalent)
// ---------------------------------------------------------------------------

/** Something that calls back once per frame with the time since the last, in ms. */
export interface FrameTicker {
  add: (callback: (deltaMs: number) => void) => () => void;
}

/** requestAnimationFrame as a ticker — the library-free default. */
export const rafTicker: FrameTicker = {
  add(callback) {
    let last = performance.now();
    let frame = requestAnimationFrame(function tick(now) {
      callback(now - last);
      last = now;
      frame = requestAnimationFrame(tick);
    });
    return () => cancelAnimationFrame(frame);
  },
};

export interface SpringFollower {
  /** Chase a new target from wherever the value is now, keeping its velocity. */
  set: (target: number) => void;
  /** Move to a value instantly, with no motion. */
  jump: (value: number) => void;
  get: () => number;
  destroy: () => void;
}

/**
 * A value that follows its target through a spring, integrating the same
 * equation of motion Motion's `useSpring` solves — so a pointer-driven spring
 * reads the same in every build. Runs only while moving; `onUpdate` receives
 * each new value.
 */
export function createSpringFollower(
  initial: number,
  onUpdate: (value: number) => void,
  options: SpringOptions & { restSpeed?: number; ticker?: FrameTicker } = {},
): SpringFollower {
  const { stiffness = 100, damping = 10, mass = 1, ticker = rafTicker } = options;
  const restDelta = options.restDelta ?? 0.01;
  const restSpeed = options.restSpeed ?? 0.01;
  let value = initial;
  let target = initial;
  let velocity = 0;
  let stop: (() => void) | null = null;

  const step = (deltaMs: number) => {
    // Fixed 1ms sub-steps keep the integration stable for stiff springs and
    // independent of the frame rate.
    const steps = Math.min(Math.max(Math.round(deltaMs), 1), 250);
    for (let i = 0; i < steps; i++) {
      const force = -stiffness * (value - target) - damping * velocity;
      velocity += (force / mass) * 0.001;
      value += velocity * 0.001;
    }
    if (Math.abs(target - value) < restDelta && Math.abs(velocity) < restSpeed) {
      value = target;
      velocity = 0;
      stop?.();
      stop = null;
    }
    onUpdate(value);
  };

  return {
    set(next) {
      target = next;
      if (!stop && value !== target) stop = ticker.add(step);
    },
    jump(next) {
      stop?.();
      stop = null;
      value = target = next;
      velocity = 0;
      onUpdate(value);
    },
    get: () => value,
    destroy() {
      stop?.();
      stop = null;
    },
  };
}

"use client";

import { cn } from "@/lib/utils";
import React, {
  createContext,
  forwardRef,
  useContext,
  useEffect,
  useImperativeHandle,
  useLayoutEffect,
  useRef,
  useState,
} from "react";
import { getThemeStyles } from "./toggle-group-theme";

// ==========================================
// THEME & CONFIGURATION
// ==========================================
export type ToggleGroupColor =
  | "primary"
  | "indigo"
  | "rose"
  | "emerald"
  | "zinc"
  | (string & {});
/**
 * `segmented` is a pill track whose highlight slides to the pressed item —
 * a view switch (Day / Week / Month). In a single group the pressed item
 * stays pressed when clicked again, and the arrow keys move the choice.
 */
export type ToggleGroupVariant = "default" | "outline" | "ghost" | "segmented";
export type ToggleGroupSize = "sm" | "md" | "lg";
export type ToggleGroupType = "single" | "multiple";

// ==========================================
// CONTEXT
// ==========================================
interface ToggleGroupContextProps {
  type: ToggleGroupType;
  value: string | string[];
  onValueChange: (value: string | string[]) => void;
  variant: ToggleGroupVariant;
  color: ToggleGroupColor;
  size: ToggleGroupSize;
  disabled: boolean;
  theme: Record<string, string>;
  /** Segmented only: the sliding highlight has been placed, so items drop their own. */
  pillReady: boolean;
}

// The segmented track. Inside a `soft` table it takes the table's own well
// (`--tbl-well`), so the tabs and the search field share one tint.
const SEGMENTED_TRACK =
  "bg-[var(--tbl-well,color-mix(in_oklab,var(--primary)_5%,color-mix(in_oklab,var(--foreground)_5%,var(--card))))]";
const SEGMENTED_PILL = "bg-card shadow-sm ring-1 ring-foreground/[0.08]";

const segmentedHeights: Record<ToggleGroupSize, string> = {
  sm: "h-9",
  md: "h-10",
  lg: "h-12",
};

// Layout effects warn during server rendering on older React; the pill is
// only ever measured in the browser anyway.
const useIsomorphicLayoutEffect =
  typeof window !== "undefined" ? useLayoutEffect : useEffect;

const ToggleGroupContext = createContext<ToggleGroupContextProps | null>(null);

function useToggleGroup() {
  const context = useContext(ToggleGroupContext);
  if (!context) {
    throw new Error("ToggleGroupItem must be used within a ToggleGroup");
  }
  return context;
}

// ==========================================
// GROUP COMPONENT
// ==========================================
/** Everything both selection modes share. */
interface ToggleGroupBaseProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "defaultValue"> {
  variant?: ToggleGroupVariant;
  color?: ToggleGroupColor;
  size?: ToggleGroupSize;
  disabled?: boolean;
}

/** The default: one item pressed at a time, so the value is a string. */
export interface ToggleGroupSingleProps extends ToggleGroupBaseProps {
  type?: "single";
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
}

/** `type="multiple"` — value and callback both deal in arrays. */
export interface ToggleGroupMultipleProps extends ToggleGroupBaseProps {
  type: "multiple";
  value?: string[];
  defaultValue?: string[];
  onValueChange?: (value: string[]) => void;
}

/**
 * Discriminated on `type`, so a single group hands your callback a `string`
 * and a multiple group hands it a `string[]`, with no cast either way.
 */
export type ToggleGroupProps = ToggleGroupSingleProps | ToggleGroupMultipleProps;

/** The two modes collapsed, which is what the implementation works with. */
type ToggleGroupImplProps = ToggleGroupBaseProps & {
  type?: ToggleGroupType;
  value?: string | string[];
  defaultValue?: string | string[];
  onValueChange?: (value: string | string[]) => void;
};

const ToggleGroupImpl = forwardRef<HTMLDivElement, ToggleGroupImplProps>(
  (
    {
      type = "single",
      value: controlledValue,
      defaultValue,
      onValueChange,
      variant = "default",
      color = "primary",
      size = "md",
      disabled = false,
      className,
      children,
      onKeyDown,
      style: styleProp,
      ...props
    },
    ref,
  ) => {
    const { theme, style } = getThemeStyles(color as string);
    const [uncontrolledValue, setUncontrolledValue] = React.useState<
      string | string[]
    >(defaultValue !== undefined ? defaultValue : type === "single" ? "" : []);

    const isControlled = controlledValue !== undefined;
    const currentValue = isControlled ? controlledValue : uncontrolledValue;

    const handleValueChange = (newValue: string | string[]) => {
      if (!isControlled) setUncontrolledValue(newValue);
      if (onValueChange) onValueChange(newValue);
    };

    const groupRef = useRef<HTMLDivElement>(null);
    useImperativeHandle(ref, () => groupRef.current as HTMLDivElement);

    // One highlight that slides between items, for a single segmented group.
    // It is measured from the pressed item, so labels of any width work.
    const sliding = variant === "segmented" && type === "single";
    const pillRef = useRef<HTMLSpanElement>(null);
    const placedRef = useRef(false);
    const [pillReady, setPillReady] = useState(false);
    const valueKey = Array.isArray(currentValue)
      ? currentValue.join("|")
      : currentValue;

    useIsomorphicLayoutEffect(() => {
      const group = groupRef.current;
      const pill = pillRef.current;
      if (!sliding || !group || !pill) return;

      const place = () => {
        const active = group.querySelector<HTMLElement>(
          '[data-toggle-item][data-state="on"]',
        );
        if (!active) {
          pill.style.opacity = "0";
          return;
        }
        const g = group.getBoundingClientRect();
        const a = active.getBoundingClientRect();
        // The first placement jumps; every later one slides.
        if (!placedRef.current) pill.style.transition = "none";
        pill.style.width = `${a.width}px`;
        pill.style.height = `${a.height}px`;
        pill.style.transform = `translate(${a.left - g.left - group.clientLeft + group.scrollLeft}px, ${a.top - g.top - group.clientTop}px)`;
        pill.style.opacity = "1";
        if (!placedRef.current) {
          void pill.offsetWidth;
          pill.style.transition = "";
          placedRef.current = true;
          setPillReady(true);
        }
      };

      place();
      const observer = new ResizeObserver(place);
      observer.observe(group);
      group
        .querySelectorAll<HTMLElement>("[data-toggle-item]")
        .forEach((item) => observer.observe(item));
      return () => observer.disconnect();
    }, [sliding, valueKey]);

    // Segmented single groups behave as a radio group: the arrow keys move
    // the choice (and focus) to the next enabled item.
    const handleKeyDown = (event: React.KeyboardEvent<HTMLDivElement>) => {
      onKeyDown?.(event);
      if (event.defaultPrevented || !sliding || disabled) return;
      const keys = ["ArrowRight", "ArrowDown", "ArrowLeft", "ArrowUp", "Home", "End"];
      if (!keys.includes(event.key)) return;
      const items = Array.from(
        groupRef.current?.querySelectorAll<HTMLButtonElement>(
          "[data-toggle-item]:not(:disabled)",
        ) ?? [],
      );
      if (!items.length) return;
      const from = items.findIndex((item) => item === document.activeElement);
      const last = items.length - 1;
      const forward = event.key === "ArrowRight" || event.key === "ArrowDown";
      const next =
        event.key === "Home"
          ? 0
          : event.key === "End"
            ? last
            : forward
              ? from >= last ? 0 : from + 1
              : from <= 0 ? last : from - 1;
      const target = items[next];
      if (!target) return;
      event.preventDefault();
      target.focus();
      const nextValue = target.dataset.value;
      if (nextValue !== undefined) handleValueChange(nextValue);
    };

    return (
      <ToggleGroupContext.Provider
        value={{
          type,
          value: currentValue,
          onValueChange: handleValueChange,
          variant,
          color,
          size,
          disabled,
          theme,
          pillReady: sliding && pillReady,
        }}
      >
        <div
          ref={groupRef}
          role={sliding ? "radiogroup" : "group"}
          className={cn(
            "inline-flex flex-wrap items-center gap-1",
            variant === "default" &&
              "p-1 rounded-xl bg-muted border border-border/50",
            variant === "segmented" &&
              cn(
                "relative flex-nowrap gap-0 rounded-full p-1",
                SEGMENTED_TRACK,
                segmentedHeights[size],
              ),
            className,
          )}
          style={{ ...style, ...styleProp }}
          onKeyDown={handleKeyDown}
          {...props}
        >
          {sliding && (
            <span
              ref={pillRef}
              aria-hidden="true"
              className={cn(
                "pointer-events-none absolute left-0 top-0 rounded-full opacity-0 transition-[transform,width,height] duration-300 ease-[cubic-bezier(0.22,1,0.36,1)] motion-reduce:transition-none",
                SEGMENTED_PILL,
              )}
            />
          )}
          {children}
        </div>
      </ToggleGroupContext.Provider>
    );
  },
);
ToggleGroupImpl.displayName = "ToggleGroup";

/**
 * The implementation is written against the collapsed props; this cast is
 * what hands callers the discriminated pair instead.
 */
export const ToggleGroup = ToggleGroupImpl as React.ForwardRefExoticComponent<
  ToggleGroupProps & React.RefAttributes<HTMLDivElement>
>;

// ==========================================
// ITEM COMPONENT
// ==========================================
export interface ToggleGroupItemProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  value: string;
}

export const ToggleGroupItem = forwardRef<
  HTMLButtonElement,
  ToggleGroupItemProps
>(({ value, disabled: itemDisabled, className, children, ...props }, ref) => {
  const context = useToggleGroup();
  const {
    type,
    value: groupValue,
    onValueChange,
    variant,
    size,
    disabled: groupDisabled,
    theme,
    pillReady,
  } = context;

  const isDisabled = groupDisabled || itemDisabled;
  const segmented = variant === "segmented";
  const radio = segmented && type === "single";

  // Check if active
  const isActive =
    type === "single"
      ? groupValue === value
      : Array.isArray(groupValue) && groupValue.includes(value);

  const handleToggle = () => {
    if (isDisabled) return;

    if (type === "single") {
      // A segmented choice is a radio: pressing it again keeps it.
      if (radio) {
        if (!isActive) onValueChange(value);
        return;
      }
      onValueChange(isActive ? "" : value);
    } else {
      const currentArray = Array.isArray(groupValue) ? groupValue : [];
      if (isActive) {
        onValueChange(currentArray.filter((v) => v !== value));
      } else {
        onValueChange([...currentArray, value]);
      }
    }
  };

  const sizeStyles = {
    sm: "h-8 px-2.5 text-xs",
    md: "h-10 px-3.5 text-sm",
    lg: "h-12 px-5 text-base",
  };

  const segmentedSizes = {
    sm: "h-full px-3 text-[13px]",
    md: "h-full px-4 text-sm",
    lg: "h-full px-5 text-base",
  };

  const getVariantStyles = () => {
    if (segmented) {
      return cn(
        "relative z-[1] whitespace-nowrap rounded-full text-muted-foreground transition-colors hover:text-foreground focus-visible:ring-primary/60 focus-visible:ring-offset-0",
        segmentedSizes[size],
        isActive && "text-foreground",
        // Until the sliding highlight is measured (and in multiple groups,
        // which have no single highlight) the pressed item paints its own.
        isActive && !pillReady && SEGMENTED_PILL,
      );
    }
    if (isActive) {
      switch (variant) {
        case "outline":
          return cn(theme.border, "shadow-sm");
        case "ghost":
          return cn(theme.text, "bg-muted");
        case "default":
        default:
          return cn(theme.bg, "shadow-md");
      }
    }

    // Inactive states
    switch (variant) {
      case "outline":
        return "border border-border bg-transparent text-muted-foreground hover:bg-muted";
      case "ghost":
        return "bg-transparent text-muted-foreground hover:bg-muted";
      case "default":
      default:
        return "bg-transparent text-muted-foreground hover:bg-muted/50";
    }
  };

  return (
    <button
      ref={ref}
      type="button"
      role={type === "single" ? "radio" : "checkbox"}
      aria-checked={isActive}
      disabled={isDisabled}
      data-toggle-item=""
      data-state={isActive ? "on" : "off"}
      data-value={value}
      // A segmented radio group is one tab stop; the arrow keys move inside it.
      tabIndex={radio ? (isActive || groupValue === "" ? 0 : -1) : undefined}
      onClick={handleToggle}
      className={cn(
        "inline-flex items-center justify-center gap-2 rounded-lg font-medium transition-all duration-200 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-zinc-400 focus-visible:ring-offset-2 disabled:opacity-50 disabled:cursor-not-allowed",
        sizeStyles[size],
        getVariantStyles(),
        className,
      )}
      {...props}
    >
      {children}
    </button>
  );
});
ToggleGroupItem.displayName = "ToggleGroupItem";

"use client";

import React from "react";

const colorThemes: Record<string, Record<string, string>> = {
  // The theme's own accent, so a group follows whatever `--primary` the
  // consumer set — the same contract Button and Input honour.
  primary: {
    bg: "bg-primary text-primary-foreground",
    text: "text-primary",
    border: "border-primary/30 text-primary bg-primary/10",
  },
  indigo: {
    bg: "bg-indigo-500 text-white",
    text: "text-indigo-600 dark:text-indigo-400",
    border:
      "border-indigo-500 text-indigo-600 dark:text-indigo-400 bg-indigo-50 dark:bg-indigo-500/10",
  },
  rose: {
    bg: "bg-rose-500 text-white",
    text: "text-rose-600 dark:text-rose-400",
    border:
      "border-rose-500 text-rose-600 dark:text-rose-400 bg-rose-50 dark:bg-rose-500/10",
  },
  emerald: {
    bg: "bg-emerald-500 text-white",
    text: "text-emerald-600 dark:text-emerald-400",
    border:
      "border-emerald-500 text-emerald-600 dark:text-emerald-400 bg-emerald-50 dark:bg-emerald-500/10",
  },
  zinc: {
    bg: "bg-zinc-900 text-white dark:bg-zinc-100 dark:text-zinc-900",
    text: "text-zinc-900 dark:text-zinc-100",
    border:
      "border-zinc-900 dark:border-zinc-100 text-zinc-900 dark:text-zinc-100 bg-zinc-100 dark:bg-zinc-800",
  },
};

const hexToRgb = (hex: string) => {
  let cleanHex = hex.replace(/^#/, "");
  if (cleanHex.length === 3)
    cleanHex = cleanHex
      .split("")
      .map((x) => x + x)
      .join("");
  const result = /^([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(cleanHex);
  return result
    ? `${parseInt(result[1], 16)}, ${parseInt(result[2], 16)}, ${parseInt(result[3], 16)}`
    : "99, 102, 241";
};

export const getThemeStyles = (color: string) => {
  if (color && color.startsWith("#")) {
    const rgb = hexToRgb(color);
    return {
      theme: {
        bg: "bg-[var(--toggle-color)] text-white",
        text: "text-[var(--toggle-color)]",
        border:
          "border-[var(--toggle-color)] text-[var(--toggle-color)] bg-[rgba(var(--toggle-rgb),0.1)]",
      },
      style: {
        "--toggle-color": color,
        "--toggle-rgb": rgb,
      } as React.CSSProperties,
    };
  }
  return { theme: colorThemes[color] || colorThemes.primary, style: {} };
};
